package com.termux.app.workspace;
import android.app.Activity;
import java.util.Arrays;
import java.util.function.Consumer;

/** Explicit UI choices; legacy terminal/Google profiles remain readable without migration. */
final class GeminiAuthUi {
    static final String[] MODES={"google","api","vertex"};
    private static String tr(Activity a,String ru,String en){return WorkspaceLanguage.code(a).equals("ru")?ru:en;}
    static String label(Activity a,String mode){switch(mode){case "google":return tr(a,"Google-аккаунт (недоступно)","Google account (unavailable)");case "vertex":return "Vertex AI · Google Cloud";case "auto":return tr(a,"Ранее выбранный вход CLI","Previously selected CLI sign-in");default:return tr(a,"Gemini API-ключ","Gemini API key");}}
    static String description(Activity a,String mode){switch(mode){case "google":return tr(a,"Текущий Gemini CLI сообщает о прекращении поддержки входа Google для личных аккаунтов. Для нового подключения выберите API-ключ или Vertex AI.","The current Gemini CLI reports that Google sign-in for individual accounts is no longer supported. Choose an API key or Vertex AI for a new connection.");case "vertex":return tr(a,"Подключение через Google Cloud: нужны настроенный Vertex AI и его учётные данные. Облачный проект — не рабочая папка. Квоты и оплата Google Cloud отдельные. Gemini API-ключ не заменяет учётные данные Vertex AI.","Connect through Google Cloud: configured Vertex AI and its credentials are required. The cloud project is not a working folder. Google Cloud quotas and billing are separate. A Gemini API key does not replace Vertex AI credentials.");case "auto":return tr(a,"Сохранённый способ входа CLI оставлен без изменений. Для смены выберите API-ключ или Vertex AI; обычный вход Google в текущем CLI недоступен.","The saved CLI authentication choice is preserved. Choose an API key or Vertex AI to change it; ordinary Google sign-in is unavailable in the current CLI.");default:return tr(a,"Вход только по Gemini API-ключу. Условия и оплата API отдельные от входа через Google.","Sign in using a Gemini API key. API terms and billing are separate from Google sign-in.");}}
    static void choose(Activity a,String current,Consumer<String> changed){String[] labels=new String[MODES.length];for(int i=0;i<labels.length;i++)labels[i]=label(a,MODES[i])+"\n"+description(a,MODES[i]);int index=Arrays.asList(MODES).indexOf(current);int checked=index==0?-1:index;
        WorkspaceDialogs.builder(a).setTitle(tr(a,"Способ входа Gemini","Gemini authentication")).setSingleChoiceItems(WorkspaceDialogs.choiceAdapter(a,labels,checked,i->i!=0),checked,(d,w)->{if(w<=0||w>=MODES.length)return;changed.accept(MODES[w]);d.dismiss();}).setNegativeButton(tr(a,"Назад","Back"),null).show();}
    static void location(Activity a,String current,Consumer<String> changed){String[] values={"global","us-central1","europe-west4","asia-northeast1"};String[] labels={"global", "us-central1", "europe-west4", "asia-northeast1",tr(a,"Указать другой регион…","Enter another location…")};WorkspaceDialogs.builder(a).setTitle(tr(a,"Регион Vertex AI","Vertex AI location")).setSingleChoiceItems(labels,Arrays.asList(values).indexOf(current),(d,w)->{d.dismiss();if(w<values.length){changed.accept(values[w]);return;}android.widget.EditText input=new android.widget.EditText(a);input.setSingleLine(true);input.setText(current);android.app.AlertDialog dialog=WorkspaceDialogs.builder(a).setTitle(tr(a,"Другой регион Vertex AI","Another Vertex AI location")).setView(input).setPositiveButton(tr(a,"Выбрать","Select"),null).setNegativeButton(tr(a,"Назад","Back"),null).create();dialog.setOnShowListener(shown->dialog.getButton(android.app.AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=input.getText().toString().trim();if(!GeminiCli.validCloudLocation(value)){input.setError(tr(a,"Укажите global или регион, например us-central1","Enter global or a location such as us-central1"));return;}changed.accept(value);dialog.dismiss();}));dialog.show();}).setNegativeButton(tr(a,"Назад","Back"),null).show();}

}
